import React, { useState, useEffect } from 'react';
import { Link, useNavigate } from 'react-router-dom';
import { getProfile, updateProfile, getOrders, requestDeleteAccount, cancelDeleteRequest } from '../services/api';
import { isAuthenticated, saveAuthData, logout } from '../util/auth';

const Account = ({ user, onUpdate }) => {
  const [profile, setProfile] = useState(null);
  const [orders, setOrders] = useState([]);
  const [loading, setLoading] = useState(true);
  const [editing, setEditing] = useState(false);
  const [formData, setFormData] = useState({
    name: '',
    email: '',
    phone: '',
    street: '',
    city: '',
    state: '',
    pincode: '',
    password: '',
    newPassword: '',
    confirmPassword: ''
  });
  const [saving, setSaving] = useState(false);
  const [message, setMessage] = useState({ type: '', text: '' });
  const [showDeleteModal, setShowDeleteModal] = useState(false);
  const [deletePassword, setDeletePassword] = useState('');
  const [deleting, setDeleting] = useState(false);
  const navigate = useNavigate();

  useEffect(() => {
    if (!isAuthenticated()) {
      navigate('/login');
      return;
    }
    fetchData();
  }, []);

  const fetchData = async () => {
    try {
      setLoading(true);
      const [profileRes, ordersRes] = await Promise.all([
        getProfile(),
        getOrders()
      ]);
      setProfile(profileRes.data);
      setOrders(ordersRes.data);
      
      setFormData(prev => ({
        ...prev,
        name: profileRes.data.name || '',
        email: profileRes.data.email || '',
        phone: profileRes.data.phone || '',
        street: profileRes.data.address?.street || '',
        city: profileRes.data.address?.city || '',
        state: profileRes.data.address?.state || '',
        pincode: profileRes.data.address?.pincode || ''
      }));
    } catch (error) {
      console.error('Error fetching data:', error);
    } finally {
      setLoading(false);
    }
  };

  const handleChange = (e) => {
    const { name, value } = e.target;
    setFormData(prev => ({
      ...prev,
      [name]: value
    }));
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    
    if (formData.newPassword && formData.newPassword !== formData.confirmPassword) {
      setMessage({ type: 'error', text: 'New passwords do not match' });
      return;
    }

    try {
      setSaving(true);
      setMessage({ type: '', text: '' });

      const updateData = {
        name: formData.name,
        phone: formData.phone,
        address: {
          street: formData.street,
          city: formData.city,
          state: formData.state,
          pincode: formData.pincode
        }
      };

      if (formData.newPassword) {
        updateData.password = formData.newPassword;
      }

      const res = await updateProfile(updateData);
      setProfile(res.data);
      saveAuthData(res.data.token, res.data);
      onUpdate(res.data);
      
      setMessage({ type: 'success', text: 'Profile updated successfully!' });
      setEditing(false);
      setFormData(prev => ({
        ...prev,
        password: '',
        newPassword: '',
        confirmPassword: ''
      }));
    } catch (error) {
      setMessage({ type: 'error', text: error.response?.data?.message || 'Error updating profile' });
    } finally {
      setSaving(false);
    }
  };

  const handleDeleteAccount = async (e) => {
    e.preventDefault();
    
    if (!deletePassword) {
      setMessage({ type: 'error', text: 'Please enter your password' });
      return;
    }

    try {
      setDeleting(true);
      setMessage({ type: '', text: '' });

      await requestDeleteAccount(deletePassword);
      
      setMessage({ type: 'success', text: 'Account deletion requested! Your account will be deleted in 30 days.' });
      setShowDeleteModal(false);
      setDeletePassword('');
      
      setTimeout(() => {
        logout();
        navigate('/');
      }, 3000);
    } catch (error) {
      setMessage({ type: 'error', text: error.response?.data?.message || 'Error requesting account deletion' });
    } finally {
      setDeleting(false);
    }
  };

  const handleCancelDeleteRequest = async () => {
    try {
      await cancelDeleteRequest();
      setMessage({ type: 'success', text: 'Account deletion cancelled successfully' });
      fetchData();
    } catch (error) {
      setMessage({ type: 'error', text: error.response?.data?.message || 'Error cancelling deletion request' });
    }
  };

  const getStatusClass = (status) => {
    const classes = {
      processing: 'bg-blue-100 text-blue-800',
      confirmed: 'bg-indigo-100 text-indigo-800',
      shipped: 'bg-purple-100 text-purple-800',
delivered: 'bg-green-100 text-green-800',
      cancelled: 'bg-red-100 text-red-800'
    };
    return classes[status] || 'bg-gray-100 text-gray-800';
  };

  if (loading) {
    return (
      <div className="flex justify-center py-12">
        <div className="spinner"></div>
      </div>
    );
  }

  return (
    <div className="fade-in">
      <div className="grid lg:grid-cols-3 gap-8">
        {/* Profile Section */}
        <div className="lg:col-span-2">
          <div className="card p-6 mb-6">
            <div className="flex items-center justify-between mb-6">
              <h2 className="text-xl font-bold text-gray-800">My Profile</h2>
              <button
                onClick={() => setEditing(!editing)}
                className="text-primary-600 hover:text-primary-700"
              >
                {editing ? 'Cancel' : 'Edit Profile'}
              </button>
            </div>

            {message.text && (
              <div className={`px-4 py-3 rounded-lg mb-4 ${
                message.type === 'error' 
                  ? 'bg-red-100 text-red-700' 
                  : 'bg-green-100 text-green-700'
              }`}>
                {message.text}
              </div>
            )}

            <form onSubmit={handleSubmit}>
              <div className="grid md:grid-cols-2 gap-4">
                <div>
                  <label className="label">Full Name</label>
                  <input
                    type="text"
                    name="name"
                    value={formData.name}
                    onChange={handleChange}
                    disabled={!editing}
                    className="input disabled:bg-gray-100 dark:disabled:bg-gray-700"
                  />
                </div>

                <div>
                  <label className="label">Email Address</label>
                  <input
                    type="email"
                    name="email"
                    value={formData.email}
                    disabled
                    className="input bg-gray-100 dark:bg-gray-700 dark:text-gray-300"
                  />
                </div>

                <div>
                  <label className="label">Phone Number</label>
                  <input
                    type="tel"
                    name="phone"
                    value={formData.phone}
                    onChange={handleChange}
                    disabled={!editing}
                    className="input disabled:bg-gray-100 dark:disabled:bg-gray-700"
                  />
                </div>

                <div>
                  <label className="label">Street Address</label>
                  <input
                    type="text"
                    name="street"
                    value={formData.street}
                    onChange={handleChange}
                    disabled={!editing}
                    className="input disabled:bg-gray-100 dark:disabled:bg-gray-700"
                  />
                </div>

                <div>
                  <label className="label">City</label>
                  <input
                    type="text"
                    name="city"
                    value={formData.city}
                    onChange={handleChange}
                    disabled={!editing}
                    className="input disabled:bg-gray-100 dark:disabled:bg-gray-700"
                  />
                </div>

                <div>
                  <label className="label">State</label>
                  <input
                    type="text"
                    name="state"
                    value={formData.state}
                    onChange={handleChange}
                    disabled={!editing}
                    className="input disabled:bg-gray-100 dark:disabled:bg-gray-700"
                  />
                </div>

                <div>
                  <label className="label">Pincode</label>
                  <input
                    type="text"
                    name="pincode"
                    value={formData.pincode}
                    onChange={handleChange}
                    disabled={!editing}
                    className="input disabled:bg-gray-100 dark:disabled:bg-gray-700"
                  />
                </div>
              </div>

              {editing && (
                <div className="mt-6 pt-6 border-t">
                  <h3 className="font-semibold text-gray-800 mb-4">Change Password (Optional)</h3>
                  <div className="grid md:grid-cols-3 gap-4">
                    <div>
                      <label className="label">New Password</label>
                      <input
                        type="password"
                        name="newPassword"
                        value={formData.newPassword}
                        onChange={handleChange}
                        className="input"
                        placeholder="New password"
                      />
                    </div>
                    <div>
                      <label className="label">Confirm Password</label>
                      <input
                        type="password"
                        name="confirmPassword"
                        value={formData.confirmPassword}
                        onChange={handleChange}
                        className="input"
                        placeholder="Confirm password"
                      />
                    </div>
                  </div>
                </div>
              )}

              {editing && (
                <button
                  type="submit"
                  disabled={saving}
                  className="btn btn-primary mt-6 disabled:opacity-50"
                >
                  {saving ? 'Saving...' : 'Save Changes'}
                </button>
              )}
            </form>
          </div>

          {/* Danger Zone - Delete Account */}
          <div className="card p-6 border-2 border-red-200">
            <h3 className="text-lg font-bold text-red-600 mb-2">Danger Zone</h3>
            <p className="text-gray-600 mb-4 text-sm">
              Once you request account deletion, your account will be scheduled for deletion in 30 days. 
              You can cancel this request anytime within 30 days.
            </p>
            
            {profile?.deleteRequestedAt ? (
              <div className="bg-yellow-50 border border-yellow-200 rounded-lg p-4 mb-4">
                <p className="text-yellow-800 font-medium">
                  Account deletion scheduled for: {new Date(profile.deleteAt).toLocaleDateString('en-IN', {
                    year: 'numeric',
                    month: 'long',
                    day: 'numeric'
                  })}
                </p>
                <p className="text-yellow-700 text-sm mt-1">
                  Your account will be permanently deleted after this date.
                </p>
                <button
                  onClick={handleCancelDeleteRequest}
                  className="btn btn-secondary mt-3"
                >
                  Cancel Deletion Request
                </button>
              </div>
            ) : (
              <button
                onClick={() => setShowDeleteModal(true)}
                className="btn bg-red-600 text-white hover:bg-red-700"
              >
                Delete Account
              </button>
            )}
          </div>
        </div>

        {/* Delete Confirmation Modal */}
        {showDeleteModal && (
          <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50 p-4">
            <div className="bg-white rounded-lg max-w-md w-full p-6">
              <div className="flex items-center justify-between mb-4">
                <h3 className="text-xl font-bold text-red-600">Delete Account?</h3>
                <button
                  onClick={() => {
                    setShowDeleteModal(false);
                    setDeletePassword('');
                  }}
                  className="text-gray-500 hover:text-gray-700 text-2xl"
                >
                  ×
                </button>
              </div>
              
              <div className="bg-red-50 border border-red-200 rounded-lg p-4 mb-4">
                <p className="text-red-800 font-medium">Are you sure?</p>
                <p className="text-red-700 text-sm mt-1">
                  This action cannot be undone. Your account will be permanently deleted after 30 days.
                </p>
              </div>

              <form onSubmit={handleDeleteAccount}>
                <div className="mb-4">
                  <label className="label">Enter your password to confirm</label>
                  <input
                    type="password"
                    value={deletePassword}
                    onChange={(e) => setDeletePassword(e.target.value)}
                    className="input"
                    placeholder="Enter your password"
                    required
                  />
                </div>

                <div className="flex gap-3">
                  <button
                    type="button"
                    onClick={() => {
                      setShowDeleteModal(false);
                      setDeletePassword('');
                    }}
                    className="btn btn-secondary flex-1"
                  >
                    Cancel
                  </button>
                  <button
                    type="submit"
                    disabled={deleting}
                    className="btn bg-red-600 text-white hover:bg-red-700 flex-1 disabled:opacity-50"
                  >
                    {deleting ? 'Deleting...' : 'Delete Account'}
                  </button>
                </div>
              </form>
            </div>
          </div>
        )}

        {/* Orders Section */}
        <div className="lg:col-span-3">
          <h2 className="text-xl font-bold text-gray-800 mb-4">My Orders</h2>
          
          {orders.length > 0 ? (
            <div className="space-y-4">
              {orders.map((order) => (
                <div key={order._id} className="card p-4">
                  <div className="flex items-center justify-between mb-4">
                    <div>
                      <p className="font-semibold text-gray-800">
                        Order #{order._id.slice(-8)}
                      </p>
                      <p className="text-sm text-gray-600">
                        {new Date(order.createdAt).toLocaleDateString('en-IN', {
                          year: 'numeric',
                          month: 'long',
                          day: 'numeric'
                        })}
                      </p>
                    </div>
                    <span className={`status-badge ${getStatusClass(order.orderStatus)}`}>
                      {order.orderStatus}
                    </span>
                  </div>
                  
                  <div className="space-y-2">
                    {order.orderItems.slice(0, 3).map((item, idx) => (
                      <div key={idx} className="flex justify-between text-sm">
                        <span className="text-gray-600">{item.name} x {item.quantity}</span>
                        <span className="text-gray-800">₹{item.price * item.quantity}</span>
                      </div>
                    ))}
                    {order.orderItems.length > 3 && (
                      <p className="text-sm text-gray-600">
                        +{order.orderItems.length - 3} more items
                      </p>
                    )}
                  </div>
                  
                  <div className="mt-4 pt-4 border-t flex justify-between">
                    <span className="font-semibold text-gray-800">Total</span>
                    <span className="font-semibold text-primary-600">₹{order.totalPrice}</span>
                  </div>
                  
                  <Link 
                    to={`/order/${order._id}`}
                    className="text-primary-600 hover:text-primary-700 text-sm mt-2 inline-block"
                  >
                    View Details →
                  </Link>
                </div>
              ))}
            </div>
          ) : (
            <div className="empty-state">
              <div className="empty-state-icon">
                <svg xmlns="http://www.w3.org/2000/svg" className="h-24 w-24" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={1} d="M20 7l-8-4-8 4m16 0l-8 4m8-4v10l-8 4m0-10L4 7m8 4v10M4 7v10l8 4" />
                </svg>
              </div>
              <h3 className="text-xl font-semibold text-gray-800 mb-2">No orders yet</h3>
              <p className="text-gray-600 mb-4">Start shopping for fresh dairy products!</p>
              <Link to="/products" className="btn btn-primary">
                Browse Products
              </Link>
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

export default Account;
